const calc = global.get('calc');
const validate = global.get('validate');
const dates = global.get('dates');
const pool = db.getPool();
const today = dates.getTodayBangkok();
const goalId = Number(msg.req.params.id);

if (!Number.isInteger(goalId) || goalId <= 0) {
    msg.statusCode = 404;
    msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
    return msg;
}

try {
    // Check goal ownership
    const [goals] = await pool.execute('SELECT * FROM savings_goals WHERE id = ? AND user_id = ? LIMIT 1', [goalId, msg.userId]);
    if (goals.length === 0) {
        msg.statusCode = 404;
        msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
        return msg;
    }
    const goal = goals[0];
    const startDateStr = goal.start_date instanceof Date ? goal.start_date.toISOString().split('T')[0] : String(goal.start_date);

    const val = validate.validateSavingPayload(msg.payload, startDateStr, today);
    if (!val.valid) {
        msg.statusCode = 400;
        msg.payload = { error: val.error };
        return msg;
    }
    const data = val.sanitized;

    // Insert transaction and recompute status within transaction
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();
        const [insertRes] = await conn.execute(`
            INSERT INTO savings_transactions (goal_id, amount, saving_date, note)
            VALUES (?, ?, ?, ?)
        `, [goalId, data.amount, data.saving_date, data.note]);

        const [txSumRow] = await conn.execute(`
            SELECT COALESCE(SUM(amount), 0) AS total
            FROM savings_transactions WHERE goal_id = ?
        `, [goalId]);
        const newTxSum = Number(txSumRow[0].total);
        const newCurrent = Number(goal.initial_amount) + newTxSum;
        const isNowCompleted = newCurrent >= Number(goal.target_amount);
        const newLifecycle = isNowCompleted ? 'completed' : 'active';

        if (goal.status !== newLifecycle) {
            await conn.execute('UPDATE savings_goals SET status = ? WHERE id = ?', [newLifecycle, goalId]);
            if (isNowCompleted) {
                // Create in-app completion notification
                await conn.execute(`
                    INSERT IGNORE INTO notifications (user_id, goal_id, type, channel, title, message, notification_date)
                    VALUES (?, ?, 'goal_completed', 'app', 'ยินดีด้วย! บรรลุเป้าหมายแล้ว', 'คุณได้ออมเงินครบตามเป้าหมายเรียบร้อยแล้ว เยี่ยมมากเลย 🎉', ?)
                `, [msg.userId, goalId, today]);
            }
        }

        await conn.commit();

        const updatedGoalObj = { ...goal, status: newLifecycle };
        const metrics = calc.computeGoalMetrics(updatedGoalObj, newTxSum, today);

        msg.statusCode = 201;
        msg.payload = {
            id: insertRes.insertId,
            goal_id: goalId,
            amount: data.amount,
            saving_date: data.saving_date,
            note: data.note,
            metrics: metrics
        };
    } catch (txErr) {
        await conn.rollback();
        throw txErr;
    } finally {
        conn.release();
    }
} catch (err) {
    node.error('Add saving error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
}
return msg;

