const calc = global.get('calc');
const dates = global.get('dates');
const pool = db.getPool();
const today = dates.getTodayBangkok();

try {
    // 1. Fetch all goals with transaction sums
    const [goalsRows] = await pool.execute(`
        SELECT g.*, COALESCE(SUM(t.amount), 0) AS tx_sum
        FROM savings_goals g
        LEFT JOIN savings_transactions t ON g.id = t.goal_id
        WHERE g.user_id = ?
        GROUP BY g.id
        ORDER BY g.created_at DESC
    `, [msg.userId]);

    let totalSaved = 0;
    let todaySavingTotal = 0;
    let activeGoalsCount = 0;
    let completedGoalsCount = 0;
    const goalsWithMetrics = [];
    const upcomingDeadlines = [];

    for (const g of goalsRows) {
        const metrics = calc.computeGoalMetrics(g, g.tx_sum, today);
        totalSaved += metrics.current;

        if (g.status === 'completed' || metrics.status === 'completed') {
            completedGoalsCount++;
        } else {
            activeGoalsCount++;
            if (!metrics.overdue) {
                todaySavingTotal += metrics.daily;
            }
            if (metrics.days_left > 0 && metrics.days_left <= 30) {
                upcomingDeadlines.push({
                    id: g.id,
                    name: g.name,
                    days_left: metrics.days_left,
                    target_date: g.target_date instanceof Date ? g.target_date.toISOString().split('T')[0] : String(g.target_date),
                    remaining: metrics.remaining,
                    status: metrics.status
                });
            }
        }

        goalsWithMetrics.push({
            id: g.id,
            name: g.name,
            target_amount: Number(g.target_amount),
            initial_amount: Number(g.initial_amount),
            start_date: g.start_date instanceof Date ? g.start_date.toISOString().split('T')[0] : String(g.start_date),
            target_date: g.target_date instanceof Date ? g.target_date.toISOString().split('T')[0] : String(g.target_date),
            status: g.status,
            metrics: metrics
        });
    }

    upcomingDeadlines.sort((a, b) => a.days_left - b.days_left);

    // 2. Fetch unread notifications count
    const [notifRows] = await pool.execute(`
        SELECT COUNT(*) AS unread_count
        FROM notifications
        WHERE user_id = ? AND is_read = 0
    `, [msg.userId]);
    const unreadCount = Number(notifRows[0].unread_count) || 0;

    // 3. Fetch latest AI analysis if available
    const [aiRows] = await pool.execute(`
        SELECT a.*, g.name as goal_name
        FROM ai_analyses a
        JOIN savings_goals g ON a.goal_id = g.id
        WHERE g.user_id = ?
        ORDER BY a.created_at DESC
        LIMIT 1
    `, [msg.userId]);
    const latestAi = aiRows.length > 0 ? aiRows[0] : null;

    msg.statusCode = 200;
    msg.payload = {
        summary: {
            total_goals: goalsRows.length,
            active_goals: activeGoalsCount,
            completed_goals: completedGoalsCount,
            total_saved: calc.round2(totalSaved)
        },
        today_saving_total: calc.round2(todaySavingTotal),
        goals: goalsWithMetrics,
        upcoming_deadlines: upcomingDeadlines,
        latest_ai: latestAi,
        unread_notifications: unreadCount
    };
} catch (err) {
    node.error('Dashboard error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
}
return msg;

const db = global.get('db');
const calc = global.get('calc');
const dates = global.get('dates');
const pool = db.getPool();
const today = dates.getTodayBangkok();
const goalId = Number(msg.req.params.id);

if (!Number.isInteger(goalId) || goalId <= 0) {
    msg.statusCode = 404;
    msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
    return msg;
}

try {
    // Check goal ownership
    const [goals] = await pool.execute('SELECT * FROM savings_goals WHERE id = ? AND user_id = ? LIMIT 1', [goalId, msg.userId]);
    if (goals.length === 0) {
        msg.statusCode = 404;
        msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
        return msg;
    }
    const goal = goals[0];
    const goalNormalized = {
        ...goal,
        start_date: goal.start_date instanceof Date ? goal.start_date.toISOString().split('T')[0] : String(goal.start_date),
        target_date: goal.target_date instanceof Date ? goal.target_date.toISOString().split('T')[0] : String(goal.target_date)
    };

    // Fetch transactions
    const [transactions] = await pool.execute(`
        SELECT amount, saving_date
        FROM savings_transactions
        WHERE goal_id = ?
        ORDER BY saving_date ASC
    `, [goalId]);
    const txNormalized = transactions.map(t => ({
        amount: Number(t.amount),
        saving_date: t.saving_date instanceof Date ? t.saving_date.toISOString().split('T')[0] : String(t.saving_date)
    }));
    const txSum = txNormalized.reduce((sum, t) => sum + t.amount, 0);

    const metrics = calc.computeGoalMetrics(goalNormalized, txSum, today);
    const chartSeries = calc.buildChartSeries(goalNormalized, txNormalized, today);

    // Latest AI analysis for this goal
    const [aiRows] = await pool.execute(`
        SELECT * FROM ai_analyses WHERE goal_id = ? ORDER BY created_at DESC LIMIT 1
    `, [goalId]);
    const latestAi = aiRows.length > 0 ? aiRows[0] : null;

    msg.statusCode = 200;
    msg.payload = {
        goal: goalNormalized,
        metrics: metrics,
        chart: chartSeries,
        latest_ai: latestAi
    };
} catch (err) {
    node.error('Analysis error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
}
return msg;

const db = global.get('db');
const calc = global.get('calc');
const dates = global.get('dates');
const ai = global.get('ai');
const pool = db.getPool();
const today = dates.getTodayBangkok();
const goalId = Number(msg.req.params.id);

if (!Number.isInteger(goalId) || goalId <= 0) {
    msg.statusCode = 404;
    msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
    return msg;
}

try {
    const [goals] = await pool.execute('SELECT * FROM savings_goals WHERE id = ? AND user_id = ? LIMIT 1', [goalId, msg.userId]);
    if (goals.length === 0) {
        msg.statusCode = 404;
        msg.payload = { error: 'ไม่พบเป้าหมายที่ระบุ' };
        return msg;
    }
    const goal = goals[0];

    const [transactions] = await pool.execute('SELECT amount, saving_date FROM savings_transactions WHERE goal_id = ? ORDER BY saving_date ASC', [goalId]);
    const txSum = transactions.reduce((sum, t) => sum + Number(t.amount), 0);
    const metrics = calc.computeGoalMetrics(goal, txSum, today);

    let analysisResult = null;
    const apiKey = env.get('LLM_API_KEY');
    const apiUrl = env.get('LLM_API_URL');
    const llmModel = env.get('LLM_MODEL') || 'gemini-1.5-flash';

    if (apiKey && apiUrl) {
        try {
            const promptText = `คุณคือผู้ช่วยวิเคราะห์การออมเงิน กรุณาวิเคราะห์เป้าหมายการออมนี้และตอบกลับเป็น JSON ภาษาไทย:
ชื่อเป้าหมาย: ${goal.name}
ยอดเป้าหมาย: ${goal.target_amount} บาท
ยอดออมปัจจุบัน: ${metrics.current} บาท
คงเหลือ: ${metrics.remaining} บาท
วันคงเหลือ: ${metrics.days_left} วัน
ออมเฉลี่ยต่อวัน: ${metrics.daily} บาท
ความคืบหน้า: ${metrics.progress}%
สถานะคำนวณ: ${metrics.status}

ตอบเฉพาะ JSON ในรูปแบบ:
{
  "status": "${metrics.status}",
  "risk_level": "low|medium|high|none",
  "summary": "สรุปสถานะสั้นๆ 1-2 ประโยค",
  "recommendation": "คำแนะนำเชิงบวกในการออม 1-2 ประโยค"
}`;

            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 6000);
            const llmRes = await fetch(apiUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${apiKey}`
                },
                body: JSON.stringify({
                    model: llmModel,
                    messages: [{ role: 'user', content: promptText }],
                    temperature: 0.3
                }),
                signal: controller.signal
            });
            clearTimeout(timeoutId);

            if (llmRes.ok) {
                const llmData = await llmRes.json();
                const content = llmData.choices?.[0]?.message?.content || llmData.candidates?.[0]?.content?.parts?.[0]?.text;
                if (content) {
                    const cleanJson = content.replace(/```json\n?|```/g, '').trim();
                    const parsed = JSON.parse(cleanJson);
                    if (ai.isValidAnalysisPayload(parsed)) {
                        analysisResult = { ...parsed, is_fallback: false };
                    }
                }
            }
        } catch (llmErr) {
            node.warn('LLM call failed, switching to rule-based fallback: ' + (llmErr.message || llmErr));
        }
    }

    if (!analysisResult) {
        analysisResult = ai.generateRuleBasedAnalysis(goal, metrics);
    }

    // Save to database
    const [insertRes] = await pool.execute(`
        INSERT INTO ai_analyses (goal_id, status, risk_level, summary, recommendation)
        VALUES (?, ?, ?, ?, ?)
    `, [goalId, analysisResult.status, analysisResult.risk_level, analysisResult.summary, analysisResult.recommendation]);

    msg.statusCode = 200;
    msg.payload = {
        id: insertRes.insertId,
        goal_id: goalId,
        status: analysisResult.status,
        risk_level: analysisResult.risk_level,
        summary: analysisResult.summary,
        recommendation: analysisResult.recommendation,
        is_fallback: analysisResult.is_fallback,
        disclaimer: 'ข้อมูลจาก AI เป็นเพียงการวิเคราะห์ข้อมูลการออมเบื้องต้น ไม่ใช่คำแนะนำทางการเงินหรือการลงทุนจากผู้เชี่ยวชาญ'
    };
} catch (err) {
    node.error('AI analyze error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
}
return msg;

