const db = global.get('db');
const calc = global.get('calc');
const dates = global.get('dates');
const pool = db.getPool();
const today = dates.getTodayBangkok();

try {
    const [goals] = await pool.execute(`
        SELECT g.*, COALESCE(SUM(t.amount), 0) AS tx_sum
        FROM savings_goals g
        LEFT JOIN savings_transactions t ON g.id = t.goal_id
        WHERE g.user_id = ? AND g.status = 'active'
        GROUP BY g.id
    `, [msg.userId]);

    let generatedCount = 0;

    for (const g of goals) {
        const metrics = calc.computeGoalMetrics(g, g.tx_sum, today);
        if (metrics.status === 'completed') continue;

        // 1. Deadline warning (within 7 days)
        if (metrics.days_left > 0 && metrics.days_left <= 7) {
            const [res] = await pool.execute(`
                INSERT IGNORE INTO notifications (user_id, goal_id, type, channel, title, message, notification_date)
                VALUES (?, ?, 'deadline_warning', 'app', ?, ?, ?)
            `, [
                msg.userId,
                g.id,
                'เตือนใกล้ครบกำหนด: ' + g.name,
                `เป้าหมาย "${g.name}" เหลือเวลาอีกเพียง ${metrics.days_left} วัน ยอดคงเหลือ ${metrics.remaining.toLocaleString('th-TH')} บาท`,
                today
            ]);
            if (res.affectedRows > 0) generatedCount++;
        }

        // 2. Daily reminder for on-track/at-risk goals
        if (metrics.daily > 0 && !metrics.overdue) {
            const [res] = await pool.execute(`
                INSERT IGNORE INTO notifications (user_id, goal_id, type, channel, title, message, notification_date)
                VALUES (?, ?, 'daily_reminder', 'app', ?, ?, ?)
            `, [
                msg.userId,
                g.id,
                'เตือนออมเงินประจำวัน: ' + g.name,
                `วันนี้อย่าลืมออมเงิน ${metrics.daily.toLocaleString('th-TH')} บาท เพื่อให้เป็นไปตามแผนนะครับ`,
                today
            ]);
            if (res.affectedRows > 0) generatedCount++;
        }
    }

    msg.statusCode = 200;
    msg.payload = {
        success: true,
        generated_count: generatedCount,
        date: today
    };
} catch (err) {
    node.error('Trigger reminders error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
}
return msg;
